import { Accordion, Separator, Text } from "@chakra-ui/react";
import { RasaCodeBlock } from "../../RasaCodeBlock";
import type { Utterance } from "../../types";
import { CommonEventInfo, DetailView, EventAccordionItem, InfoField } from "./blocks";
import { BotLatencyAccordionItem } from "./LatencyDetails";

// Provenance labels for skill-engine responses (mantle_response_source). Absent
// for CALM utterances, so the Type field simply does not render there.
const RESPONSE_TYPE_LABELS: Record<string, string> = {
  verbatim: "Verbatim response",
  rephrased: "Rephrased response",
  llm: "LLM generated",
  filler: "Filler",
};

interface BotMessageInfoProps {
  utterance: Utterance;
  onClose: () => void;
}

export const BotMessageInfo = ({ utterance, onClose }: BotMessageInfoProps) => {
  const utterAction = utterance.metadata?.utter_action;
  const responseSource = utterance.metadata?.mantle_response_source;
  const responseType = responseSource ? RESPONSE_TYPE_LABELS[responseSource] : undefined;

  return (
    <DetailView title="Agent response details" onClose={onClose}>
      {utterAction && (
        <InfoField label="Name">
          <Text textStyle="sm" wordBreak="break-all">
            {utterAction}
          </Text>
        </InfoField>
      )}

      {utterance.text && (
        <InfoField label="Text">
          <Text textStyle="sm" whiteSpace="pre-wrap">
            {utterance.text}
          </Text>
        </InfoField>
      )}

      {responseType && (
        <InfoField label="Type">
          <Text textStyle="sm" data-testid="agent-response-type">
            {responseType}
          </Text>
        </InfoField>
      )}

      {utterance.rephrase && (
        <>
          <InfoField label="Original response">
            <Text textStyle="sm">{utterance.metadata?.domain_ground_truth ?? "-"}</Text>
          </InfoField>

          <InfoField label="Rephrased response">
            <Text textStyle="sm">{utterance.text ?? "-"}</Text>
          </InfoField>
        </>
      )}

      <Separator mt="2" />

      <Accordion.Root collapsible multiple>
        <BotLatencyAccordionItem executionTimes={utterance.metadata?.execution_times} />
        {utterance.responseData?.custom && (
          <EventAccordionItem title="Custom response" value="custom-response">
            <RasaCodeBlock code={JSON.stringify(utterance.responseData.custom, null, 2)} />
          </EventAccordionItem>
        )}
        <EventAccordionItem title="Event details" value="event-details">
          <CommonEventInfo event={{ ...utterance, conversationEventType: "BOT" }} />
        </EventAccordionItem>
      </Accordion.Root>
    </DetailView>
  );
};
